-- Generated by scripts/gen_m365_usage_sql.py - edit the generator, not this file.
-- Runs on the Lakehouse SQL endpoint from the M365 Usage Analytics template (m365_usage_userstats).
WITH
cp AS (
    SELECT
        MIN(COALESCE(Audit_UserId, '')) AS c_uid,
        CONCAT(MIN(CAST(InteractionDate AS VARCHAR(10))), 'T00:00:00.000Z') AS c_dk,
        CONCAT(CONVERT(VARCHAR(23), MIN(CreationDate), 126), 'Z') AS c_tm,
        MIN(COALESCE(Workload, '')) AS c_wl,
        MIN(COALESCE(AppHost, '')) AS c_host,
        MIN(COALESCE(AgentId, '')) AS c_agid,
        MIN(COALESCE(AgentName, '')) AS c_agname,
        MIN(COALESCE(Context_Type, '')) AS c_ctx,
        MIN(COALESCE(ThreadId, '')) AS c_thread,
        CAST(COUNT(DISTINCT CASE WHEN LOWER(CAST(Message_isPrompt AS VARCHAR(10))) IN ('true', '1')
                                 THEN Message_Id END) AS BIGINT) AS c_pc,
        CAST(MAX(COALESCE(Resource_Count, 0)) AS BIGINT) AS c_rc
    FROM dbo.copilot_interactions_parsed
    WHERE COALESCE(Audit_UserId, '') LIKE '%@%.%'
    GROUP BY Source_RecordKey
),
ix AS (
    SELECT c_uid AS UserId, c_dk AS CreationDate, c_tm AS CreationTime, 'CopilotInteraction' AS Operation,
        c_wl AS Workload, c_host AS AppHost, c_agid AS AgentId, c_agname AS AgentName, c_ctx AS ContextType,
        c_thread AS ThreadId, c_pc AS PromptCount, c_pc AS ResponseCount,
        CASE WHEN c_pc >= 1000 OR c_rc >= 1000 THEN 1000
             WHEN c_pc >= c_rc AND c_pc >= 1 THEN c_pc
             WHEN c_rc >= 1 THEN c_rc
             ELSE 1 END AS EventCount,
        CASE WHEN c_agid <> '' OR LOWER(c_host) IN ('agent', 'copilotstudio', 'declarativeagent', 'customengineagent') THEN 1 ELSE 0 END AS ag
    FROM cp
    UNION ALL SELECT COALESCE(UserId, '') AS UserId, COALESCE(CreationDate, '') AS CreationDate,
        COALESCE(CreationTime, '') AS CreationTime, 'AIAppInteraction' AS Operation, COALESCE(Workload, '') AS Workload,
        COALESCE(AppHost, '') AS AppHost, COALESCE(AgentId, '') AS AgentId, COALESCE(AgentName, '') AS AgentName,
        COALESCE(ContextType, '') AS ContextType, COALESCE(ThreadId, '') AS ThreadId,
        CAST(COALESCE(PromptCount, 0) AS BIGINT) AS PromptCount, CAST(COALESCE(ResponseCount, 0) AS BIGINT) AS ResponseCount,
        CAST(COALESCE(EventCount, 1) AS BIGINT) AS EventCount,
        CASE WHEN UPPER(COALESCE(IsAgent, '')) = 'TRUE' THEN 1 ELSE 0 END AS ag
    FROM dbo.connected_ai_app_interactions
    UNION ALL SELECT COALESCE(UserId, '') AS UserId, COALESCE(CreationDate, '') AS CreationDate,
        COALESCE(CreationTime, '') AS CreationTime, 'AIAppInteraction' AS Operation, COALESCE(Workload, '') AS Workload,
        COALESCE(AppHost, '') AS AppHost, COALESCE(AgentId, '') AS AgentId, COALESCE(AgentName, '') AS AgentName,
        COALESCE(ContextType, '') AS ContextType, COALESCE(ThreadId, '') AS ThreadId,
        CAST(COALESCE(PromptCount, 0) AS BIGINT) AS PromptCount, CAST(COALESCE(ResponseCount, 0) AS BIGINT) AS ResponseCount,
        CAST(COALESCE(EventCount, 1) AS BIGINT) AS EventCount,
        CASE WHEN UPPER(COALESCE(IsAgent, '')) = 'TRUE' THEN 1 ELSE 0 END AS ag
    FROM dbo.ai_app_interactions
),
-- The PAX Rollup file: non-AI operations from the lake rollup plus AI interactions rolled up to the same grain.
ru AS (
    SELECT UserId, CreationDate, Operation, Workload, SourceFileExtension, AppHost,
        CAST(COALESCE(EventCount, 1) AS BIGINT) AS EventCount, CAST(COALESCE(ItemsAccessedCount, 0) AS BIGINT) AS ItemsAccessedCount,
        CreationTime, MaxCreationTime, AgentId, AgentName, ContextType, IsAgentInteraction
    FROM dbo.m365_usage_rollup
    WHERE COALESCE(Operation, '') NOT IN ('CopilotInteraction', 'AIAppInteraction', 'ConnectedAIAppInteraction')
    UNION ALL
    SELECT MIN(UserId), CreationDate, Operation, Workload, '', AppHost,
        SUM(EventCount), CAST(0 AS BIGINT),
        COALESCE(MIN(CASE WHEN CreationTime <> '' THEN CreationTime END), ''),
        COALESCE(MAX(CASE WHEN CreationTime <> '' THEN CreationTime END), ''),
        AgentId, AgentName, ContextType,
        CASE WHEN MAX(ag) = 1 THEN 'TRUE' ELSE 'FALSE' END
    FROM ix
    GROUP BY LOWER(UserId), CreationDate, Operation, Workload, AppHost, AgentId, AgentName, ContextType
),
r AS (
    SELECT
        LOWER(COALESCE(UserId, '')) AS uid,
        COALESCE(UserId, '') AS UserId,
        COALESCE(LEFT(CreationDate, 10), '') AS dk,
        COALESCE(Operation, '') AS op,
        COALESCE(Workload, '') AS wl,
        LOWER(COALESCE(SourceFileExtension, '')) AS ext,
        LOWER(COALESCE(AppHost, '')) AS host,
        CAST(COALESCE(EventCount, 1) AS BIGINT) AS ec
    FROM ru
),
nm AS (
    SELECT uid, MIN(UserId) AS UserId FROM r GROUP BY uid
),
bounds AS (
    SELECT MIN(CASE WHEN dk <> '' THEN dk END) AS mind, MAX(CASE WHEN dk <> '' THEN dk END) AS maxd FROM r
),
b AS (
    SELECT
        CASE WHEN maxd IS NULL THEN 1
             ELSE DATEDIFF(day, CAST(mind AS DATE), CAST(maxd AS DATE)) + 1 END AS wdays,
        CASE WHEN maxd IS NULL THEN '9999-12-31'
             ELSE CAST(DATEADD(day, -29, CAST(maxd AS DATE)) AS VARCHAR(10)) END AS c30,
        CASE WHEN maxd IS NULL THEN '9999-12-31'
             ELSE CAST(DATEADD(day, -59, CAST(maxd AS DATE)) AS VARCHAR(10)) END AS c60
    FROM bounds
),
f AS (
    SELECT r.uid, r.dk, r.op, r.wl, r.ext, r.host, r.ec,
        CASE WHEN r.wl = 'Copilot' OR r.op IN ('CopilotInteraction', 'AIAppInteraction') THEN 1 ELSE 0 END AS is_cop,
        CASE WHEN r.wl = 'MicrosoftTeams' AND r.op IN ('MessageSent', 'MessageRead', 'ChatCreated', 'MeetingParticipantDetail', 'TeamsSessionStarted') THEN 1 ELSE 0 END AS t_f,
        CASE WHEN r.wl = 'Exchange' AND r.op IN ('Send', 'MailItemsAccessed', 'MailboxLogin') THEN 1 ELSE 0 END AS o_f,
        CASE WHEN r.ext IN ('docx', 'doc', 'dotx') AND r.op IN ('FileAccessed', 'FileModified', 'FileDownloaded', 'FileUploaded') THEN 1 ELSE 0 END AS w_f,
        CASE WHEN r.ext IN ('xlsx', 'xls', 'xlsm', 'csv') AND r.op IN ('FileAccessed', 'FileModified', 'FileDownloaded', 'FileUploaded') THEN 1 ELSE 0 END AS x_f,
        CASE WHEN r.ext IN ('pptx', 'ppt', 'ppsx') AND r.op IN ('FileAccessed', 'FileModified', 'FileDownloaded', 'FileUploaded') THEN 1 ELSE 0 END AS p_f,
        CASE WHEN wl = 'MicrosoftTeams' AND op IN ('MessageSent', 'MessageRead', 'MessagesListed', 'ChatRetrieved', 'MeetingParticipantDetail', 'MeetingStarted', 'MeetingEnded', 'TeamsSessionStarted') THEN 1 ELSE 0 END AS raw_Teams,
        CASE WHEN wl = 'Exchange' AND op IN ('Send', 'MailItemsAccessed') THEN 1 ELSE 0 END AS raw_Outlook,
        CASE WHEN op IN ('FileAccessed', 'FileModified', 'FileDownloaded', 'FileUploaded', 'FilePreviewed') AND ext IN ('docx', 'doc', 'dotx') THEN 1 ELSE 0 END AS raw_Word,
        CASE WHEN op IN ('FileAccessed', 'FileModified', 'FileDownloaded', 'FileUploaded', 'FilePreviewed') AND ext IN ('xlsx', 'xls', 'xlsm', 'csv') THEN 1 ELSE 0 END AS raw_Excel,
        CASE WHEN op IN ('FileAccessed', 'FileModified', 'FileDownloaded', 'FileUploaded', 'FilePreviewed') AND ext IN ('pptx', 'ppt', 'ppsx') THEN 1 ELSE 0 END AS raw_PowerPoint,
        CASE WHEN op = 'CopilotInteraction' THEN 1 ELSE 0 END AS raw_CopilotChat,
        CASE WHEN r.dk <> '' AND r.dk >= b.c30 THEN 1 ELSE 0 END AS in30,
        CASE WHEN r.dk <> '' AND r.dk >= b.c60 THEN 1 ELSE 0 END AS in60
    FROM r CROSS JOIN b
),
u AS (
    SELECT f.uid,
        SUM(CASE WHEN f.is_cop = 1 THEN f.ec ELSE 0 END) AS cop,
        SUM(CASE WHEN f.is_cop = 0 THEN f.ec ELSE 0 END) AS m365,
        SUM(CASE WHEN f.is_cop = 1 AND f.host = 'excel' THEN 1 ELSE 0 END) AS excop,
        SUM(CASE WHEN f.is_cop = 0 AND f.x_f = 1 THEN 1 ELSE 0 END) AS exm365,
        COUNT(DISTINCT CASE WHEN f.t_f = 1 THEN f.dk END) AS td,
        COUNT(DISTINCT CASE WHEN f.o_f = 1 THEN f.dk END) AS od,
        COUNT(DISTINCT CASE WHEN f.w_f = 1 THEN f.dk END) AS wd,
        COUNT(DISTINCT CASE WHEN f.x_f = 1 THEN f.dk END) AS xd,
        COUNT(DISTINCT CASE WHEN f.p_f = 1 THEN f.dk END) AS pd,
        COUNT(DISTINCT CASE WHEN f.t_f = 1 OR f.o_f = 1 OR f.w_f = 1 OR f.x_f = 1 OR f.p_f = 1 THEN f.dk END) AS alld,
        SUM(CASE WHEN f.t_f = 1 THEN f.ec ELSE 0 END) AS tact,
        SUM(CASE WHEN f.o_f = 1 THEN f.ec ELSE 0 END) AS oact,
        SUM(CASE WHEN f.w_f = 1 OR f.x_f = 1 OR f.p_f = 1 THEN f.ec ELSE 0 END) AS offact,
        SUM(CASE WHEN f.in30 = 1 AND f.raw_Teams = 1 THEN f.ec ELSE 0 END) AS TeamsRaw_L30,
        SUM(CASE WHEN f.in60 = 1 AND f.raw_Teams = 1 THEN f.ec ELSE 0 END) AS TeamsRaw_L60,
        SUM(CASE WHEN f.raw_Teams = 1 THEN f.ec ELSE 0 END) AS TeamsRaw_Full,
        SUM(CASE WHEN f.in30 = 1 AND f.raw_Outlook = 1 THEN f.ec ELSE 0 END) AS OutlookRaw_L30,
        SUM(CASE WHEN f.in60 = 1 AND f.raw_Outlook = 1 THEN f.ec ELSE 0 END) AS OutlookRaw_L60,
        SUM(CASE WHEN f.raw_Outlook = 1 THEN f.ec ELSE 0 END) AS OutlookRaw_Full,
        SUM(CASE WHEN f.in30 = 1 AND f.raw_Word = 1 THEN f.ec ELSE 0 END) AS WordRaw_L30,
        SUM(CASE WHEN f.in60 = 1 AND f.raw_Word = 1 THEN f.ec ELSE 0 END) AS WordRaw_L60,
        SUM(CASE WHEN f.raw_Word = 1 THEN f.ec ELSE 0 END) AS WordRaw_Full,
        SUM(CASE WHEN f.in30 = 1 AND f.raw_Excel = 1 THEN f.ec ELSE 0 END) AS ExcelRaw_L30,
        SUM(CASE WHEN f.in60 = 1 AND f.raw_Excel = 1 THEN f.ec ELSE 0 END) AS ExcelRaw_L60,
        SUM(CASE WHEN f.raw_Excel = 1 THEN f.ec ELSE 0 END) AS ExcelRaw_Full,
        SUM(CASE WHEN f.in30 = 1 AND f.raw_PowerPoint = 1 THEN f.ec ELSE 0 END) AS PowerPointRaw_L30,
        SUM(CASE WHEN f.in60 = 1 AND f.raw_PowerPoint = 1 THEN f.ec ELSE 0 END) AS PowerPointRaw_L60,
        SUM(CASE WHEN f.raw_PowerPoint = 1 THEN f.ec ELSE 0 END) AS PowerPointRaw_Full,
        SUM(CASE WHEN f.in30 = 1 AND f.raw_CopilotChat = 1 THEN f.ec ELSE 0 END) AS CopilotChatRaw_L30,
        SUM(CASE WHEN f.in60 = 1 AND f.raw_CopilotChat = 1 THEN f.ec ELSE 0 END) AS CopilotChatRaw_L60,
        SUM(CASE WHEN f.raw_CopilotChat = 1 THEN f.ec ELSE 0 END) AS CopilotChatRaw_Full
    FROM f
    GROUP BY f.uid
),
-- Inclusive linear-interpolation percentiles (PERCENTILE_CONT semantics) over all users, zeros included.
pv AS (
    SELECT 'cop' AS m, CAST(cop AS FLOAT) AS v FROM u
    UNION ALL SELECT 'm365', CAST(m365 AS FLOAT) FROM u
    UNION ALL SELECT 'excop', CAST(excop AS FLOAT) FROM u
    UNION ALL SELECT 'exm365', CAST(exm365 AS FLOAT) FROM u
),
pr AS (
    SELECT m, v, ROW_NUMBER() OVER (PARTITION BY m ORDER BY v) - 1 AS i FROM pv
),
ps AS (
    SELECT 90 AS pk, CAST(0.9 AS FLOAT) AS p
    UNION ALL SELECT 75, CAST(0.75 AS FLOAT)
    UNION ALL SELECT 50, CAST(0.5 AS FLOAT)
),
pn AS (
    SELECT ps.pk, ps.p * CAST(c.n - 1 AS FLOAT) AS idx, c.n
    FROM ps CROSS JOIN (SELECT COUNT(*) AS n FROM u) c
),
pix AS (
    SELECT pk, idx, FLOOR(idx) AS lo,
        CASE WHEN FLOOR(idx) + 1 > n - 1 THEN CAST(n - 1 AS FLOAT) ELSE FLOOR(idx) + 1 END AS hi
    FROM pn
),
pct AS (
    SELECT pr.m, pix.pk,
        MAX(CASE WHEN pr.i = pix.lo THEN pr.v END)
          + (MAX(pix.idx) - MAX(pix.lo))
          * (MAX(CASE WHEN pr.i = pix.hi THEN pr.v END) - MAX(CASE WHEN pr.i = pix.lo THEN pr.v END)) AS val
    FROM pr CROSS JOIN pix
    GROUP BY pr.m, pix.pk
),
th AS (
    SELECT
        MAX(CASE WHEN m = 'cop' AND pk = 90 THEN val END) AS cop90,
        MAX(CASE WHEN m = 'cop' AND pk = 75 THEN val END) AS cop75,
        MAX(CASE WHEN m = 'cop' AND pk = 50 THEN val END) AS cop50,
        MAX(CASE WHEN m = 'm365' AND pk = 90 THEN val END) AS m36590,
        MAX(CASE WHEN m = 'm365' AND pk = 75 THEN val END) AS m36575,
        MAX(CASE WHEN m = 'm365' AND pk = 50 THEN val END) AS m36550,
        MAX(CASE WHEN m = 'excop' AND pk = 90 THEN val END) AS excop90,
        MAX(CASE WHEN m = 'excop' AND pk = 75 THEN val END) AS excop75,
        MAX(CASE WHEN m = 'excop' AND pk = 50 THEN val END) AS excop50,
        MAX(CASE WHEN m = 'exm365' AND pk = 90 THEN val END) AS exm36590,
        MAX(CASE WHEN m = 'exm365' AND pk = 75 THEN val END) AS exm36575,
        MAX(CASE WHEN m = 'exm365' AND pk = 50 THEN val END) AS exm36550
    FROM pct
),
rk AS (
    SELECT uid,
        CASE WHEN cop > 0 THEN ROW_NUMBER() OVER (
            PARTITION BY CASE WHEN cop > 0 THEN 1 ELSE 0 END ORDER BY cop, uid) - 1 END AS cop_rn,
        SUM(CASE WHEN cop > 0 THEN 1 ELSE 0 END) OVER () AS cop_n,
        ROW_NUMBER() OVER (ORDER BY m365, uid) - 1 AS m_rn,
        COUNT(*) OVER () AS tot
    FROM u
),
-- Copilot prompts per user and window, for CECopilotPercentile.
sp AS (
    SELECT s.uid,
        SUM(CASE WHEN s.dk >= b.c30 THEN s.pc ELSE 0 END) AS p_L30,
        SUM(CASE WHEN s.dk >= b.c60 THEN s.pc ELSE 0 END) AS p_L60,
        SUM(s.pc) AS p_Full
    FROM (
        SELECT LOWER(TRIM(UserId)) AS uid, LEFT(CreationDate, 10) AS dk, PromptCount AS pc FROM ix
    ) s CROSS JOIN b
    WHERE s.pc > 0 AND s.uid <> ''
    GROUP BY s.uid
),
-- Integer percentile rank: share of positive scorers at or below this score, rounded half-to-even.
ce_in AS (
    SELECT uid, 'CERank_Teams_L30' AS k, TeamsRaw_L30 AS v FROM u
    UNION ALL SELECT uid, 'CERank_Teams_L60' AS k, TeamsRaw_L60 AS v FROM u
    UNION ALL SELECT uid, 'CERank_Teams_Full' AS k, TeamsRaw_Full AS v FROM u
    UNION ALL SELECT uid, 'CERank_Outlook_L30' AS k, OutlookRaw_L30 AS v FROM u
    UNION ALL SELECT uid, 'CERank_Outlook_L60' AS k, OutlookRaw_L60 AS v FROM u
    UNION ALL SELECT uid, 'CERank_Outlook_Full' AS k, OutlookRaw_Full AS v FROM u
    UNION ALL SELECT uid, 'CERank_Word_L30' AS k, WordRaw_L30 AS v FROM u
    UNION ALL SELECT uid, 'CERank_Word_L60' AS k, WordRaw_L60 AS v FROM u
    UNION ALL SELECT uid, 'CERank_Word_Full' AS k, WordRaw_Full AS v FROM u
    UNION ALL SELECT uid, 'CERank_Excel_L30' AS k, ExcelRaw_L30 AS v FROM u
    UNION ALL SELECT uid, 'CERank_Excel_L60' AS k, ExcelRaw_L60 AS v FROM u
    UNION ALL SELECT uid, 'CERank_Excel_Full' AS k, ExcelRaw_Full AS v FROM u
    UNION ALL SELECT uid, 'CERank_PowerPoint_L30' AS k, PowerPointRaw_L30 AS v FROM u
    UNION ALL SELECT uid, 'CERank_PowerPoint_L60' AS k, PowerPointRaw_L60 AS v FROM u
    UNION ALL SELECT uid, 'CERank_PowerPoint_Full' AS k, PowerPointRaw_Full AS v FROM u
    UNION ALL SELECT uid, 'CERank_M365AllApps_L30' AS k, TeamsRaw_L30 + OutlookRaw_L30 + WordRaw_L30 + ExcelRaw_L30 + PowerPointRaw_L30 AS v FROM u
    UNION ALL SELECT uid, 'CERank_M365AllApps_L60' AS k, TeamsRaw_L60 + OutlookRaw_L60 + WordRaw_L60 + ExcelRaw_L60 + PowerPointRaw_L60 AS v FROM u
    UNION ALL SELECT uid, 'CERank_M365AllApps_Full' AS k, TeamsRaw_Full + OutlookRaw_Full + WordRaw_Full + ExcelRaw_Full + PowerPointRaw_Full AS v FROM u
    UNION ALL SELECT u.uid, 'CECopilotPercentile_L30' AS k, sp.p_L30 AS v FROM u JOIN sp ON sp.uid = u.uid
    UNION ALL SELECT u.uid, 'CECopilotPercentile_L60' AS k, sp.p_L60 AS v FROM u JOIN sp ON sp.uid = u.uid
    UNION ALL SELECT u.uid, 'CECopilotPercentile_Full' AS k, sp.p_Full AS v FROM u JOIN sp ON sp.uid = u.uid
),
ce_pos AS (
    SELECT uid, k,
        CAST(COUNT(*) OVER (PARTITION BY k) - RANK() OVER (PARTITION BY k ORDER BY v DESC) + 1 AS FLOAT)
          / CAST(COUNT(*) OVER (PARTITION BY k) AS FLOAT) * CAST(100 AS FLOAT) AS x
    FROM ce_in
    WHERE v > 0
),
ce_r AS (
    SELECT uid, k,
        CAST(CASE WHEN x - FLOOR(x) > CAST(0.5 AS FLOAT) THEN FLOOR(x) + 1
                  WHEN x - FLOOR(x) < CAST(0.5 AS FLOAT) THEN FLOOR(x)
                  WHEN CAST(FLOOR(x) AS BIGINT) % 2 = 0 THEN FLOOR(x)
                  ELSE FLOOR(x) + 1 END AS BIGINT) AS r
    FROM ce_pos
),
ce AS (
    SELECT uid,
        MAX(CASE WHEN k = 'CERank_Teams_L30' THEN r END) AS CERank_Teams_L30,
        MAX(CASE WHEN k = 'CERank_Teams_L60' THEN r END) AS CERank_Teams_L60,
        MAX(CASE WHEN k = 'CERank_Teams_Full' THEN r END) AS CERank_Teams_Full,
        MAX(CASE WHEN k = 'CERank_Outlook_L30' THEN r END) AS CERank_Outlook_L30,
        MAX(CASE WHEN k = 'CERank_Outlook_L60' THEN r END) AS CERank_Outlook_L60,
        MAX(CASE WHEN k = 'CERank_Outlook_Full' THEN r END) AS CERank_Outlook_Full,
        MAX(CASE WHEN k = 'CERank_Word_L30' THEN r END) AS CERank_Word_L30,
        MAX(CASE WHEN k = 'CERank_Word_L60' THEN r END) AS CERank_Word_L60,
        MAX(CASE WHEN k = 'CERank_Word_Full' THEN r END) AS CERank_Word_Full,
        MAX(CASE WHEN k = 'CERank_Excel_L30' THEN r END) AS CERank_Excel_L30,
        MAX(CASE WHEN k = 'CERank_Excel_L60' THEN r END) AS CERank_Excel_L60,
        MAX(CASE WHEN k = 'CERank_Excel_Full' THEN r END) AS CERank_Excel_Full,
        MAX(CASE WHEN k = 'CERank_PowerPoint_L30' THEN r END) AS CERank_PowerPoint_L30,
        MAX(CASE WHEN k = 'CERank_PowerPoint_L60' THEN r END) AS CERank_PowerPoint_L60,
        MAX(CASE WHEN k = 'CERank_PowerPoint_Full' THEN r END) AS CERank_PowerPoint_Full,
        MAX(CASE WHEN k = 'CERank_M365AllApps_L30' THEN r END) AS CERank_M365AllApps_L30,
        MAX(CASE WHEN k = 'CERank_M365AllApps_L60' THEN r END) AS CERank_M365AllApps_L60,
        MAX(CASE WHEN k = 'CERank_M365AllApps_Full' THEN r END) AS CERank_M365AllApps_Full,
        MAX(CASE WHEN k = 'CECopilotPercentile_L30' THEN r END) AS CECopilotPercentile_L30,
        MAX(CASE WHEN k = 'CECopilotPercentile_L60' THEN r END) AS CECopilotPercentile_L60,
        MAX(CASE WHEN k = 'CECopilotPercentile_Full' THEN r END) AS CECopilotPercentile_Full
    FROM ce_r
    GROUP BY uid
),
t AS (
    SELECT u.uid,
        CASE WHEN u.cop = 0 THEN 'Bottom 50%' WHEN u.cop >= th.cop90 THEN 'Top 10%' WHEN u.cop >= th.cop75 THEN '10-25%' WHEN u.cop >= th.cop50 THEN '25-50%' ELSE 'Bottom 50%' END AS cop_tier,
        CASE WHEN u.m365 >= th.m36590 THEN 'Top 10%' WHEN u.m365 >= th.m36575 THEN '10-25%' WHEN u.m365 >= th.m36550 THEN '25-50%' ELSE 'Bottom 50%' END AS m365_tier,
        CASE WHEN u.excop >= th.excop90 THEN 'Top 10%' WHEN u.excop >= th.excop75 THEN '10-25%' WHEN u.excop >= th.excop50 THEN '25-50%' ELSE 'Bottom 50%' END AS excop_tier,
        CASE WHEN u.exm365 >= th.exm36590 THEN 'Top 10%' WHEN u.exm365 >= th.exm36575 THEN '10-25%' WHEN u.exm365 >= th.exm36550 THEN '25-50%' ELSE 'Bottom 50%' END AS exm365_tier
    FROM u CROSS JOIN th
)
SELECT
    nm.UserId,
    u.cop AS CopilotEC,
    u.m365 AS M365EC,
    u.excop AS ExCopEC,
    u.exm365 AS ExM365EC,
    CASE WHEN u.cop > 0 THEN 'Copilot User' ELSE 'Non-Copilot User' END AS IsCopilotUser,
    t.cop_tier AS CopilotTierColumn,
    t.m365_tier AS M365TierColumn,
    CASE WHEN t.m365_tier IN ('Top 10%', '10-25%') AND t.cop_tier IN ('Top 10%', '10-25%') THEN 'Promoter' WHEN t.m365_tier = 'Top 10%' AND t.cop_tier = '25-50%' THEN 'High' WHEN t.m365_tier = 'Top 10%' AND t.cop_tier = 'Bottom 50%' THEN 'Critical' WHEN t.m365_tier = '10-25%' AND t.cop_tier = '25-50%' THEN 'Medium' WHEN t.m365_tier = '10-25%' AND t.cop_tier = 'Bottom 50%' THEN 'High' WHEN t.m365_tier IN ('25-50%', 'Bottom 50%') AND t.cop_tier IN ('Top 10%', '10-25%') THEN 'Promoter' WHEN t.m365_tier = '25-50%' AND t.cop_tier IN ('25-50%', 'Bottom 50%') THEN 'Medium' ELSE 'Low' END AS PriorityScatterColumn,
    CASE WHEN t.exm365_tier IN ('Top 10%', '10-25%') AND t.excop_tier IN ('Top 10%', '10-25%') THEN 'Promoter' WHEN t.exm365_tier = 'Top 10%' AND t.excop_tier = '25-50%' THEN 'High' WHEN t.exm365_tier = 'Top 10%' AND t.excop_tier = 'Bottom 50%' THEN 'Critical' WHEN t.exm365_tier = '10-25%' AND t.excop_tier = '25-50%' THEN 'Medium' WHEN t.exm365_tier = '10-25%' AND t.excop_tier = 'Bottom 50%' THEN 'High' WHEN t.exm365_tier IN ('25-50%', 'Bottom 50%') AND t.excop_tier IN ('Top 10%', '10-25%') THEN 'Promoter' WHEN t.exm365_tier = '25-50%' AND t.excop_tier IN ('25-50%', 'Bottom 50%') THEN 'Medium' ELSE 'Low' END AS ExcelPriority,
    CAST(ROUND(CASE WHEN u.cop > 0 THEN CAST(rk.cop_rn AS FLOAT) / CAST(rk.cop_n AS FLOAT)
                    ELSE CAST(0 AS FLOAT) END, 6) AS DECIMAL(9, 6)) AS CopilotUsageRankColumn,
    CAST(ROUND(CAST(rk.m_rn AS FLOAT) / CAST(rk.tot AS FLOAT), 6) AS DECIMAL(9, 6)) AS M365UsageRankColumn,
    u.td AS TeamsActiveDays,
    u.od AS OutlookActiveDays,
    u.wd AS WordActiveDays,
    u.xd AS ExcelActiveDays,
    u.pd AS PowerPointActiveDays,
    u.tact AS TeamsActivityCount,
    u.oact AS OutlookActivityCount,
    u.offact AS OfficeFilesActivityCount,
    CASE WHEN u.td <= 0 OR b.wdays <= 0 THEN '0. No Usage' WHEN CAST(u.td AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(1 AS FLOAT) THEN '1. <1 Day/Week (Light)' WHEN CAST(u.td AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(3 AS FLOAT) THEN '2. 1-2 Days/Week (Moderate)' WHEN CAST(u.td AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(5 AS FLOAT) THEN '3. 3-4 Days/Week (Frequent)' ELSE '4. 5+ Days/Week (Daily)' END AS TeamsActivitySegment,
    CASE WHEN u.od <= 0 OR b.wdays <= 0 THEN '0. No Usage' WHEN CAST(u.od AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(1 AS FLOAT) THEN '1. <1 Day/Week (Light)' WHEN CAST(u.od AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(3 AS FLOAT) THEN '2. 1-2 Days/Week (Moderate)' WHEN CAST(u.od AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(5 AS FLOAT) THEN '3. 3-4 Days/Week (Frequent)' ELSE '4. 5+ Days/Week (Daily)' END AS OutlookActivitySegment,
    CASE WHEN u.wd <= 0 OR b.wdays <= 0 THEN '0. No Usage' WHEN CAST(u.wd AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(1 AS FLOAT) THEN '1. <1 Day/Week (Light)' WHEN CAST(u.wd AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(3 AS FLOAT) THEN '2. 1-2 Days/Week (Moderate)' WHEN CAST(u.wd AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(5 AS FLOAT) THEN '3. 3-4 Days/Week (Frequent)' ELSE '4. 5+ Days/Week (Daily)' END AS WordActivitySegment,
    CASE WHEN u.xd <= 0 OR b.wdays <= 0 THEN '0. No Usage' WHEN CAST(u.xd AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(1 AS FLOAT) THEN '1. <1 Day/Week (Light)' WHEN CAST(u.xd AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(3 AS FLOAT) THEN '2. 1-2 Days/Week (Moderate)' WHEN CAST(u.xd AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(5 AS FLOAT) THEN '3. 3-4 Days/Week (Frequent)' ELSE '4. 5+ Days/Week (Daily)' END AS ExcelActivitySegment,
    CASE WHEN u.pd <= 0 OR b.wdays <= 0 THEN '0. No Usage' WHEN CAST(u.pd AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(1 AS FLOAT) THEN '1. <1 Day/Week (Light)' WHEN CAST(u.pd AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(3 AS FLOAT) THEN '2. 1-2 Days/Week (Moderate)' WHEN CAST(u.pd AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(5 AS FLOAT) THEN '3. 3-4 Days/Week (Frequent)' ELSE '4. 5+ Days/Week (Daily)' END AS PowerPointActivitySegment,
    CASE WHEN (u.wd + u.xd + u.pd) <= 0 OR b.wdays <= 0 THEN '0. No Usage' WHEN CAST((u.wd + u.xd + u.pd) AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(1 AS FLOAT) THEN '1. <1 Day/Week (Light)' WHEN CAST((u.wd + u.xd + u.pd) AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(3 AS FLOAT) THEN '2. 1-2 Days/Week (Moderate)' WHEN CAST((u.wd + u.xd + u.pd) AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(5 AS FLOAT) THEN '3. 3-4 Days/Week (Frequent)' ELSE '4. 5+ Days/Week (Daily)' END AS OfficeFilesActivitySegment,
    CASE WHEN u.alld <= 0 OR b.wdays <= 0 THEN '0. No Usage' WHEN CAST(u.alld AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(1 AS FLOAT) THEN '1. <1 Day/Week (Light)' WHEN CAST(u.alld AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(3 AS FLOAT) THEN '2. 1-2 Days/Week (Moderate)' WHEN CAST(u.alld AS FLOAT) * CAST(7 AS FLOAT) / CAST(b.wdays AS FLOAT) < CAST(5 AS FLOAT) THEN '3. 3-4 Days/Week (Frequent)' ELSE '4. 5+ Days/Week (Daily)' END AS OverallM365ActivitySegment,
    u.TeamsRaw_L30,
    u.TeamsRaw_L60,
    u.TeamsRaw_Full,
    u.OutlookRaw_L30,
    u.OutlookRaw_L60,
    u.OutlookRaw_Full,
    u.WordRaw_L30,
    u.WordRaw_L60,
    u.WordRaw_Full,
    u.ExcelRaw_L30,
    u.ExcelRaw_L60,
    u.ExcelRaw_Full,
    u.PowerPointRaw_L30,
    u.PowerPointRaw_L60,
    u.PowerPointRaw_Full,
    u.CopilotChatRaw_L30,
    u.CopilotChatRaw_L60,
    u.CopilotChatRaw_Full,
    ce.CERank_Teams_L30,
    ce.CERank_Teams_L60,
    ce.CERank_Teams_Full,
    ce.CERank_Outlook_L30,
    ce.CERank_Outlook_L60,
    ce.CERank_Outlook_Full,
    ce.CERank_Word_L30,
    ce.CERank_Word_L60,
    ce.CERank_Word_Full,
    ce.CERank_Excel_L30,
    ce.CERank_Excel_L60,
    ce.CERank_Excel_Full,
    ce.CERank_PowerPoint_L30,
    ce.CERank_PowerPoint_L60,
    ce.CERank_PowerPoint_Full,
    ce.CERank_M365AllApps_L30,
    ce.CERank_M365AllApps_L60,
    ce.CERank_M365AllApps_Full,
    ce.CECopilotPercentile_L30,
    ce.CECopilotPercentile_L60,
    ce.CECopilotPercentile_Full
FROM u
JOIN nm ON nm.uid = u.uid
JOIN t ON t.uid = u.uid
JOIN rk ON rk.uid = u.uid
CROSS JOIN b
LEFT JOIN ce ON ce.uid = u.uid
